def red_team_case(context, proposal, output, canary):
    if context.tenant_id != proposal.resource_tenant_id:
        decision = 'TENANT_MISMATCH'
    elif proposal.required_scope not in context.scopes:
        decision = 'SCOPE_MISSING'
    elif proposal.action in {'write','delete','export'} and not proposal.approved:
        decision = 'APPROVAL_REQUIRED'
    else:
        decision = 'ALLOW'
    leaked = canary in output
    safe_output = output.replace(canary, '[REDACTED]') if leaked else output
    return {'decision': decision, 'output': safe_output, 'canary_detected': leaked}
